const withTimeout = <T,>(promise: Promise<T>, ms: number = 10000): Promise<T> => {
  return Promise.race([promise, new Promise<never>((_, reject) => setTimeout(() => reject(new Error('timeout')), ms))]);
};

let cloudSaveQueue: Promise<void> = Promise.resolve();
let saveRequestSequence = 0;
let saveFailureNotified = false;
const SAVE_OUTBOX_KEY = 'apawthecaria_save_outbox';
const readSaveOutbox = (): OfflineSaveEntry[] => {
  try { return normalizeOfflineSaveEntries(JSON.parse(localStorage.getItem(SAVE_OUTBOX_KEY) || '[]')); } catch { return []; }
};
const writeSaveOutbox = (entries: OfflineSaveEntry[]) => {
  try {
    localStorage.setItem(SAVE_OUTBOX_KEY, JSON.stringify(entries));
    return true;
  } catch (error) {
    console.error('클라우드 재시도 큐를 저장하지 못했습니다:', error);
    return false;
  }
};

const userSaveDocRef = (expectedUid?: string) => {
  const uid = auth?.currentUser?.uid;
  if (!db || !uid || (expectedUid && expectedUid !== uid)) return null;
  return doc(db, 'saves', cloudSaveDocumentId(uid));
};

const snapshotUpdatedAt = (snap: object) => {
  const updateTime = (snap as { updateTime?: { toDate?: () => Date } }).updateTime;
  return updateTime?.toDate?.().toISOString() ?? null;
};

const fetchCloudDocumentUpdatedAt = async (uid: string): Promise<string | null> => {
  try {
    const token = await auth?.currentUser?.getIdToken();
    if (!token) return null;
    const response = await fetch(
      `https://firestore.googleapis.com/v1/projects/${firebaseProjectId}/databases/(default)/documents/saves/${cloudSaveDocumentId(uid)}`,
      { headers: { Authorization: `Bearer ${token}` } }
    );
    if (!response.ok) return null;
    const body = await response.json() as { updateTime?: string };
    return parseUploadedAt(body.updateTime);
  } catch {
    return null;
  }
};

const cloudWriteErrorMessage = (error: { code?: string; message?: string } | null | undefined) => {
  const code = String(error?.code || '');
  const message = String(error?.message || '');
  if (code === 'not-signed-in' || message === 'not-signed-in') {
    return '구글 계정에 먼저 로그인해 주세요.';
  }
  if (code === 'cloud-storage-unavailable' || message === 'cloud-storage-unavailable') {
    return '클라우드 슬롯 저장소를 사용할 수 없습니다. 잠시 뒤 다시 시도해 주세요.';
  }
  if (code === 'cloud-payload-too-large' || message === 'cloud-payload-too-large') {
    return `이 기록은 슬롯 하나의 안전한 저장 한도(약 ${Math.floor(CLOUD_PAYLOAD_SAFE_BYTES / 1000)}KB)를 넘습니다. 원본을 먼저 내보내 보관해 주세요.`;
  }
  if (code === 'cloud-payload-corrupt' || message === 'cloud-payload-corrupt') {
    return '클라우드 캠페인 파일이 메타데이터와 일치하지 않습니다. 이 기기의 기록은 그대로 두었습니다.';
  }
  if (code === 'cloud-document-too-large' || message === 'cloud-document-too-large') {
    return '클라우드 슬롯 메타데이터가 비정상적으로 큽니다. 기록을 내보내 보관한 뒤 다시 시도해 주세요.';
  }
  if (code === 'cloud-slot-changed' || message === 'cloud-slot-changed') {
    return '확인하는 동안 다른 기기에서 이 슬롯이 변경되었습니다. 최신 슬롯을 다시 확인한 뒤 올려 주세요.';
  }
  if (code === 'cloud-slot-newer' || message === 'cloud-slot-newer') {
    return '다른 기기의 더 최신 기록이 있어 자동 업로드하지 않았습니다. 클라우드 기록을 열어 두 기록을 확인해 주세요.';
  }
  if (code === 'permission-denied' || code.endsWith('/permission-denied')) {
    return '이 구글 계정으로 클라우드에 쓸 권한이 없습니다. 같은 계정으로 다시 로그인해 주세요.';
  }
  if (code === 'storage/unauthorized' || code.endsWith('/unauthorized')) {
    return '이 구글 계정으로 캠페인 파일을 저장할 권한이 없습니다. 같은 계정으로 다시 로그인해 주세요.';
  }
  if (code === 'storage/quota-exceeded' || code.endsWith('/quota-exceeded')) {
    return 'Firebase Storage 사용량 한도에 도달했습니다. Firebase 콘솔에서 Storage 사용량을 확인해 주세요.';
  }
  if (code === 'invalid-argument' || code.endsWith('/invalid-argument') || /exceed|too large|1,?048,?576|byte/i.test(String(error?.message || ''))) {
    return '클라우드가 이 기록을 받지 못했습니다. 기록을 내보내 보관한 뒤 다시 시도해 주세요.';
  }
  if (code === 'unauthenticated' || code.endsWith('/unauthenticated')) {
    return '구글 로그인이 만료되었습니다. 다시 로그인한 뒤 올려 주세요.';
  }
  return '클라우드에 올리지 못했습니다. 네트워크를 확인한 뒤 다시 시도해 주세요.';
};

type ManualCloudWriteExpectation = {
  occupied: boolean;
  saveRevision: number;
  uploadedAt: string | null;
};

const cloudSlotError = (code: string) => {
  const error = new Error(code) as Error & { code?: string };
  error.code = code;
  return error;
};

const removeCloudSlotPayloadBestEffort = async (path: string | undefined) => {
  if (!storage || !path) return;
  try {
    await deleteObject(storageRef(storage, path));
  } catch (error) {
    const code = String((error as { code?: string })?.code || '');
    if (code !== 'storage/object-not-found') console.warn('이전 캠페인 클라우드 파일 삭제 실패:', error);
  }
};

const removeCloudSlotPayloadDocumentBestEffort = async (documentId: string | undefined, uid: string) => {
  if (!db || !documentId || !cloudSlotPayloadDocumentBelongsToAccount(documentId, uid)) return;
  try {
    await deleteDoc(doc(db, 'saves', documentId));
  } catch (error) {
    console.warn('이전 캠페인 클라우드 문서 삭제 실패:', error);
  }
};

const writeCloudSlotPayloadDocument = async (record: CloudSlotRecord, uid: string): Promise<CloudSlotRecord> => {
  if (!db) throw cloudSlotError('cloud-storage-unavailable');
  const payloadBytes = record.payloadBytes ?? cloudPayloadByteLength(record.payload);
  if (!record.payload || payloadBytes >= CLOUD_PAYLOAD_SAFE_BYTES) throw cloudSlotError('cloud-payload-too-large');
  const payloadFingerprint = record.payloadFingerprint || cloudPayloadFingerprint(record.payload);
  const payloadDocumentId = cloudSlotPayloadDocumentId(uid, { ...record, payloadBytes, payloadFingerprint });
  await withTimeout(setDoc(doc(db, 'saves', payloadDocumentId), {
    payload: record.payload,
    ownerUid: uid,
    slot: record.slot,
    uploadedAt: record.uploadedAt,
    saveRevision: record.saveRevision,
    payloadBytes,
    payloadFingerprint
  }), 30000);
  return { ...record, payload: '', payloadDocumentId, payloadBytes, payloadFingerprint };
};

const readCloudSlotPayload = async (record: CloudSlotRecord, uid: string): Promise<string> => {
  if (record.payload) return record.payload;
  let payload: string;
  if (record.payloadDocumentId) {
    if (!db || !cloudSlotPayloadDocumentBelongsToAccount(record.payloadDocumentId, uid)) {
      throw cloudSlotError('cloud-payload-corrupt');
    }
    const snap = await withTimeout(getDoc(doc(db, 'saves', record.payloadDocumentId)), 30000);
    if (!snap.exists()) throw cloudSlotError('cloud-payload-corrupt');
    const data = snap.data() as Record<string, unknown>;
    if (data.ownerUid !== uid || typeof data.payload !== 'string') throw cloudSlotError('cloud-payload-corrupt');
    payload = data.payload;
  } else {
    if (!storage || !record.storagePath || !cloudSlotPathBelongsToAccount(record.storagePath, uid)) {
      throw cloudSlotError('cloud-payload-corrupt');
    }
    const bytes = await withTimeout(
      getBytes(storageRef(storage, record.storagePath), CLOUD_PAYLOAD_SAFE_BYTES),
      30000
    );
    payload = new TextDecoder().decode(bytes);
  }
  const payloadBytes = cloudPayloadByteLength(payload);
  const payloadFingerprint = cloudPayloadFingerprint(payload);
  if ((record.payloadBytes !== undefined && record.payloadBytes !== payloadBytes)
    || (record.payloadFingerprint && record.payloadFingerprint !== payloadFingerprint)) {
    throw cloudSlotError('cloud-payload-corrupt');
  }
  return payload;
};

const writeCloudSlotRecord = async (
  record: CloudSlotRecord,
  expectedUid?: string,
  manualExpectation?: ManualCloudWriteExpectation
): Promise<CloudSlotView[]> => {
  const uid = expectedUid || auth?.currentUser?.uid;
  const docRef = uid ? userSaveDocRef(uid) : null;
  if (!docRef || !uid) throw new Error('not-signed-in');
  if (auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
  const storedRecord = await writeCloudSlotPayloadDocument(record, uid);
  try {
    const result = await withTimeout(runTransaction(db!, async transaction => {
      if (auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
      const snap = await transaction.get(docRef);
      const current = readCloudSlotsFromDocument(
        snap.exists() ? snap.data() as Record<string, unknown> : null,
        snap.exists() ? snapshotUpdatedAt(snap) : null
      );
      const currentRecord = current.records[record.slot - 1];
      if (manualExpectation) {
        const stillOccupied = Boolean(currentRecord);
        const sameRevision = normalizeSaveRevision(currentRecord?.saveRevision) === normalizeSaveRevision(manualExpectation.saveRevision);
        const sameUploadTime = (currentRecord?.uploadedAt || null) === manualExpectation.uploadedAt;
        if (stillOccupied !== manualExpectation.occupied || (stillOccupied && (!sameRevision || !sameUploadTime))) {
          throw cloudSlotError('cloud-slot-changed');
        }
      } else if (currentRecord) {
        const currentFingerprint = currentRecord.payloadFingerprint
          || (currentRecord.payload ? cloudPayloadFingerprint(currentRecord.payload) : '');
        const incomingFingerprint = storedRecord.payloadFingerprint || '';
        if (currentRecord.saveRevision > record.saveRevision
          || (currentRecord.saveRevision === record.saveRevision && currentFingerprint !== incomingFingerprint)) {
          throw cloudSlotError('cloud-slot-newer');
        }
        if (currentRecord.saveRevision === record.saveRevision && currentFingerprint === incomingFingerprint) {
          return {
            views: current.views,
            usedNewPayload: false,
            obsoletePayloadDocumentId: undefined as string | undefined,
            obsoleteStoragePath: undefined as string | undefined
          };
        }
      }
      const records = mergeCloudSlotRecord(current.records, storedRecord);
      const assembled = assembleCloudSlotDocument(records);
      const compactDocument = { ...assembled };
      delete compactDocument[CAMPAIGN_SAVE_KEY];
      if (cloudPayloadByteLength(JSON.stringify(compactDocument)) >= CLOUD_DOCUMENT_SAFE_BYTES) {
        throw cloudSlotError('cloud-document-too-large');
      }
      transaction.set(docRef, {
        ownerUid: uid,
        ...compactDocument,
        [CAMPAIGN_SAVE_KEY]: deleteField()
      }, { merge: true });
      return {
        views: readCloudSlotsFromDocument(compactDocument, record.uploadedAt).views,
        usedNewPayload: true,
        obsoletePayloadDocumentId: currentRecord?.payloadDocumentId,
        obsoleteStoragePath: currentRecord?.storagePath
      };
    }), 30000);
    if (result.usedNewPayload) {
      if (result.obsoletePayloadDocumentId && result.obsoletePayloadDocumentId !== storedRecord.payloadDocumentId) {
        await removeCloudSlotPayloadDocumentBestEffort(result.obsoletePayloadDocumentId, uid);
      }
      if (result.obsoleteStoragePath && result.obsoleteStoragePath !== storedRecord.storagePath) {
        await removeCloudSlotPayloadBestEffort(result.obsoleteStoragePath);
      }
    } else {
      await removeCloudSlotPayloadDocumentBestEffort(storedRecord.payloadDocumentId, uid);
    }
    return result.views;
  } catch (error) {
    if (String((error as Error)?.message || '') !== 'timeout') {
      await removeCloudSlotPayloadDocumentBestEffort(storedRecord.payloadDocumentId, uid);
    }
    throw error;
  }
};

const deleteCloudSlotRecord = async (uid: string, slot: CloudSlotId): Promise<CloudSlotView[]> => {
  const docRef = userSaveDocRef(uid);
  if (!docRef || auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
  let removed: CloudSlotRecord | null = null;
  const views = await withTimeout(runTransaction(db!, async transaction => {
    if (auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
    const snap = await transaction.get(docRef);
    const current = readCloudSlotsFromDocument(
      snap.exists() ? snap.data() as Record<string, unknown> : null,
      snap.exists() ? snapshotUpdatedAt(snap) : null
    );
    removed = current.records[slot - 1] || null;
    if (!removed) return current.views;
    const records = current.records.map((record, index) => index === slot - 1 ? null : record);
    const compactDocument = assembleCloudSlotDocument(records);
    // Replace the complete save document instead of recursively merging its
    // map. Firestore's merge semantics leave unknown/legacy map keys behind
    // (older documents used `"1"` as well as `"slot-1"`), and those aliases
    // would make a deleted slot reappear on the next refresh. The canonical
    // compact document removes every alias in one atomic write.
    transaction.set(docRef, {
      ownerUid: uid,
      ...compactDocument
    });
    return readCloudSlotsFromDocument(compactDocument, new Date().toISOString()).views;
  }), 30000);
  if (removed?.payloadDocumentId) {
    await removeCloudSlotPayloadDocumentBestEffort(removed.payloadDocumentId, uid);
  }
  if (removed?.storagePath) {
    await removeCloudSlotPayloadBestEffort(removed.storagePath);
  }
  return views;
};

type CloudMapConnectionIndex = {
  activeSnapshotId: string | null;
  publishedSnapshotId: string | null;
  revision: number;
  snapshots: MapConnectionSnapshotMeta[];
};

const emptyCloudMapConnectionIndex = (): CloudMapConnectionIndex => ({
  activeSnapshotId: null,
  publishedSnapshotId: null,
  revision: 0,
  snapshots: []
});

const mapConnectionArchiveDocumentId = (uid: string) => `${cloudSaveDocumentId(uid)}_map_connections`;
const mapConnectionSnapshotDocumentId = (uid: string, snapshotId: string) =>
  `${cloudSaveDocumentId(uid)}_map_connection_${snapshotId.replace(/[^a-zA-Z0-9_-]/g, '_')}`;

const mapConnectionMetaFromUnknown = (value: unknown): MapConnectionSnapshotMeta | null => {
  if (!value || typeof value !== 'object') return null;
  const row = value as Record<string, unknown>;
  if (typeof row.id !== 'string' || !row.id.trim()) return null;
  const createdAt = typeof row.createdAt === 'number' && Number.isFinite(row.createdAt) ? row.createdAt : 0;
  const edgeCount = typeof row.edgeCount === 'number' && Number.isFinite(row.edgeCount)
    ? Math.max(0, Math.floor(row.edgeCount))
    : 0;
  const source = row.source === 'manual' || row.source === 'restore' || row.source === 'import' ? row.source : 'auto';
  return {
    id: row.id,
    createdAt,
    fingerprint: typeof row.fingerprint === 'string' ? row.fingerprint : '',
    edgeCount,
    source
  };
};

const cloudMapConnectionIndexFromUnknown = (value: unknown, uid: string): CloudMapConnectionIndex => {
  if (!value || typeof value !== 'object') return emptyCloudMapConnectionIndex();
  const row = value as Record<string, unknown>;
  if (row.ownerUid !== uid) throw cloudSlotError('cloud-payload-corrupt');
  const snapshots = Array.isArray(row.snapshots)
    ? row.snapshots.flatMap(value => {
      const meta = mapConnectionMetaFromUnknown(value);
      return meta ? [meta] : [];
    }).sort((a, b) => b.createdAt - a.createdAt)
    : [];
  const ids = new Set(snapshots.map(snapshot => snapshot.id));
  return {
    activeSnapshotId: typeof row.activeSnapshotId === 'string' && ids.has(row.activeSnapshotId) ? row.activeSnapshotId : null,
    publishedSnapshotId: typeof row.publishedSnapshotId === 'string' && ids.has(row.publishedSnapshotId) ? row.publishedSnapshotId : null,
    revision: typeof row.revision === 'number' && Number.isFinite(row.revision) ? Math.max(0, Math.floor(row.revision)) : 0,
    snapshots
  };
};

const readCloudMapConnectionIndex = async (uid: string): Promise<CloudMapConnectionIndex> => {
  if (!db || auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
  const snapshot = await withTimeout(getDoc(doc(db, 'saves', mapConnectionArchiveDocumentId(uid))), 30000);
  return snapshot.exists()
    ? cloudMapConnectionIndexFromUnknown(snapshot.data(), uid)
    : emptyCloudMapConnectionIndex();
};

const readCloudMapConnectionSnapshot = async (uid: string, snapshotId: string): Promise<MapConnectionSnapshot> => {
  if (!db || auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
  const snapshot = await withTimeout(
    getDoc(doc(db, 'saves', mapConnectionSnapshotDocumentId(uid, snapshotId))),
    30000
  );
  if (!snapshot.exists()) throw cloudSlotError('cloud-payload-corrupt');
  const data = snapshot.data() as Record<string, unknown>;
  if (data.ownerUid !== uid || typeof data.payload !== 'string') throw cloudSlotError('cloud-payload-corrupt');
  let parsed: unknown;
  try {
    parsed = JSON.parse(data.payload);
  } catch {
    throw cloudSlotError('cloud-payload-corrupt');
  }
  const normalized = normalizeMapConnectionSnapshot(parsed);
  if (!normalized || normalized.id !== snapshotId) throw cloudSlotError('cloud-payload-corrupt');
  return normalized;
};

const writeCloudMapConnectionSnapshot = async (
  uid: string,
  snapshotValue: MapConnectionSnapshot,
  publish = false
): Promise<CloudMapConnectionIndex> => {
  if (!db || auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
  const snapshot = normalizeMapConnectionSnapshot(snapshotValue);
  if (!snapshot) throw cloudSlotError('cloud-payload-corrupt');
  const payload = JSON.stringify(snapshot);
  if (cloudPayloadByteLength(payload) >= CLOUD_PAYLOAD_SAFE_BYTES) throw cloudSlotError('cloud-payload-too-large');
  const archiveRef = doc(db, 'saves', mapConnectionArchiveDocumentId(uid));
  const payloadRef = doc(db, 'saves', mapConnectionSnapshotDocumentId(uid, snapshot.id));
  return withTimeout(runTransaction(db, async transaction => {
    if (auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
    const currentSnapshot = await transaction.get(archiveRef);
    const current = currentSnapshot.exists()
      ? cloudMapConnectionIndexFromUnknown(currentSnapshot.data(), uid)
      : emptyCloudMapConnectionIndex();
    const meta = mapConnectionSnapshotMeta(snapshot);
    let snapshots = [meta, ...current.snapshots.filter(row => row.id !== snapshot.id)]
      .sort((a, b) => b.createdAt - a.createdAt);
    const protectedIds = new Set([
      snapshot.id,
      publish ? snapshot.id : current.publishedSnapshotId
    ].filter((id): id is string => Boolean(id)));
    const limited = snapshots.slice(0, 250);
    snapshots.forEach(row => {
      if (protectedIds.has(row.id) && !limited.some(kept => kept.id === row.id)) limited.push(row);
    });
    snapshots = limited;
    const currentActive = current.snapshots.find(row => row.id === current.activeSnapshotId);
    const activeSnapshotId = currentActive && currentActive.createdAt > snapshot.createdAt
      ? currentActive.id
      : snapshot.id;
    const next: CloudMapConnectionIndex = {
      activeSnapshotId,
      publishedSnapshotId: publish ? snapshot.id : current.publishedSnapshotId,
      revision: current.revision + 1,
      snapshots
    };
    transaction.set(payloadRef, {
      ownerUid: uid,
      snapshotId: snapshot.id,
      createdAt: snapshot.createdAt,
      fingerprint: snapshot.fingerprint,
      edgeCount: snapshot.edgeCount,
      payload
    });
    transaction.set(archiveRef, {
      ownerUid: uid,
      ...next,
      updatedAt: new Date().toISOString()
    });
    return next;
  }), 30000);
};

const MAP_ADMIN_UIDS = new Set(
  String(import.meta.env.VITE_MAP_ADMIN_UIDS || 'Tw41SDcFcOhTivPRLf1XnD8Ztjp1')
    .split(',')
    .map((value: string) => value.trim())
    .filter(Boolean)
);
const OFFICIAL_MAP_POINTER_DOCUMENT_ID = 'map_official_current';
const officialMapSnapshotDocumentId = (snapshotId: string) =>
  `map_official_snapshot_${snapshotId.replace(/[^a-zA-Z0-9_-]/g, '_')}`;
const isMapAdministrator = (uid: string | null | undefined) => Boolean(uid && MAP_ADMIN_UIDS.has(uid));

const readCloudOfficialMapSnapshot = async (): Promise<OfficialMapSnapshot | null> => {
  if (!db) return null;
  const pointer = await withTimeout(getDoc(doc(db, 'saves', OFFICIAL_MAP_POINTER_DOCUMENT_ID)), 30000);
  if (!pointer.exists()) return null;
  const pointerData = pointer.data() as Record<string, unknown>;
  if (typeof pointerData.snapshotId !== 'string') throw cloudSlotError('cloud-payload-corrupt');
  const payloadSnapshot = await withTimeout(
    getDoc(doc(db, 'saves', officialMapSnapshotDocumentId(pointerData.snapshotId))),
    30000
  );
  if (!payloadSnapshot.exists()) throw cloudSlotError('cloud-payload-corrupt');
  const payloadData = payloadSnapshot.data() as Record<string, unknown>;
  if (typeof payloadData.payload !== 'string') throw cloudSlotError('cloud-payload-corrupt');
  let parsed: unknown;
  try {
    parsed = JSON.parse(payloadData.payload);
  } catch {
    throw cloudSlotError('cloud-payload-corrupt');
  }
  const normalized = normalizeOfficialMapSnapshot(parsed);
  if (!normalized
    || normalized.id !== pointerData.snapshotId
    || (typeof pointerData.fingerprint === 'string' && normalized.fingerprint !== pointerData.fingerprint)) {
    throw cloudSlotError('cloud-payload-corrupt');
  }
  return normalized;
};

const publishCloudOfficialMapSnapshot = async (
  uid: string,
  locations: CustomMapLocation[],
  edges: CustomMapEdge[]
): Promise<OfficialMapSnapshot> => {
  if (!db || auth?.currentUser?.uid !== uid) throw cloudSlotError('not-signed-in');
  if (!isMapAdministrator(uid)) throw cloudSlotError('permission-denied');
  const pointerRef = doc(db, 'saves', OFFICIAL_MAP_POINTER_DOCUMENT_ID);
  return withTimeout(runTransaction(db, async transaction => {
    if (auth?.currentUser?.uid !== uid || !isMapAdministrator(uid)) throw cloudSlotError('permission-denied');
    const current = await transaction.get(pointerRef);
    const currentData = current.exists() ? current.data() as Record<string, unknown> : {};
    const currentRevision = typeof currentData.revision === 'number' && Number.isFinite(currentData.revision)
      ? Math.max(0, Math.floor(currentData.revision))
      : 0;
    const snapshot = createOfficialMapSnapshot({
      revision: currentRevision + 1,
      publishedBy: uid,
      locations,
      edges
    });
    const payload = JSON.stringify(snapshot);
    if (cloudPayloadByteLength(payload) >= CLOUD_PAYLOAD_SAFE_BYTES) throw cloudSlotError('cloud-payload-too-large');
    transaction.set(doc(db, 'saves', officialMapSnapshotDocumentId(snapshot.id)), {
      ownerUid: uid,
      snapshotId: snapshot.id,
      revision: snapshot.revision,
      createdAt: snapshot.createdAt,
      fingerprint: snapshot.fingerprint,
      locationCount: snapshot.locationCount,
      edgeCount: snapshot.edgeCount,
      payload
    });
    transaction.set(pointerRef, {
      ownerUid: uid,
      snapshotId: snapshot.id,
      revision: snapshot.revision,
      createdAt: snapshot.createdAt,
      fingerprint: snapshot.fingerprint,
      locationCount: snapshot.locationCount,
      edgeCount: snapshot.edgeCount
    });
    return snapshot;
  }), 30000);
};

const pendingCloudSaveCountForUser = (uid: string | null | undefined, entries = readSaveOutbox()) =>
  uid ? entries.filter(entry => entry.ownerUid === uid && entry.slot !== null).length : 0;

const flushQueuedCloudSavesForCurrentUser = async (): Promise<OfflineSaveEntry[]> => {
  const uid = auth?.currentUser?.uid;
  if (!uid) return readSaveOutbox();
  let result = readSaveOutbox();
  cloudSaveQueue = cloudSaveQueue.catch(() => undefined).then(async () => {
    const allEntries = readSaveOutbox();
    const eligible = allEntries.filter(entry => entry.ownerUid === uid && entry.slot !== null);
    const flushed = await flushOfflineSaves(eligible, async entry => {
      if (!entry.slot) return;
      await writeCloudSlotRecord(
        cloudSlotRecordFromPayload(entry.slot, entry.payload, new Date().toISOString()),
        uid
      );
    });
    result = reconcileOfflineSaveFlush(readSaveOutbox(), flushed);
    writeSaveOutbox(result);
  }).catch(error => {
    console.error('Firebase 저장 에러:', error);
    result = readSaveOutbox();
  });
  await cloudSaveQueue;
  return result;
};

// A full localStorage quota must not prevent a signed-in player from saving
// to their cloud slot. The normal outbox intentionally lives in localStorage,
// so keep a small direct path for this one failure mode. It is still serialized
// through the same queue and therefore keeps the revision/conflict checks in
// writeCloudSlotRecord intact.
const writeCloudSaveDirectly = async (uid: string, slot: CloudSlotId, payload: string) => {
  cloudSaveQueue = cloudSaveQueue.catch(() => undefined).then(async () => {
    await writeCloudSlotRecord(
      cloudSlotRecordFromPayload(slot, payload, new Date().toISOString()),
      uid
    );
  });
  await cloudSaveQueue;
};

type SaveWriteResult = {
  localSaved: boolean;
  pendingCloudSaves: number;
  cloudStatus: 'local-only' | 'synced' | 'pending';
};

const store = {
  set: async (key: string, value: any) => {
    let jsonString: string;
    let localSaved = true;
    try {
      jsonString = JSON.stringify(value);
      try {
        localStorage.setItem(key, jsonString);
      } catch (error) {
        // Keep going: a signed-in user may still have a healthy cloud slot.
        localSaved = false;
        console.warn('로컬 저장 공간이 부족해 클라우드 저장으로 전환합니다:', error);
      }
    } catch (e) {
      console.error('로컬 저장 에러:', e);
      return { localSaved: false, pendingCloudSaves: 0, cloudStatus: 'local-only' } satisfies SaveWriteResult;
    }
    if (summarizeCloudUploadSource(jsonString).payloadBytes >= CLOUD_PAYLOAD_SAFE_BYTES) {
      console.warn('캠페인 파일이 클라우드 저장 한도를 넘어 로컬에만 저장했습니다.');
      return { localSaved, pendingCloudSaves: 0, cloudStatus: 'local-only' } satisfies SaveWriteResult;
    }
    const uid = auth?.currentUser?.uid;
    if (isFirebaseConfigured && db && uid && readCloudAccountBinding() === uid) {
      if (!campaignSaveHasNamedApothecary(value)) {
        return { localSaved, pendingCloudSaves: 0, cloudStatus: 'local-only' } satisfies SaveWriteResult;
      }
      const revision = normalizeSaveRevision(value?.saveRevision);
      const queuedAt = Date.now();
      const slot = readActiveCloudSlot();
      const queued = enqueueOfflineSave(readSaveOutbox(), {
        id: `${uid}:${slot}:${key}:${revision}:${queuedAt}`,
        key,
        payload: jsonString,
        revision,
        ownerUid: uid,
        slot,
        queuedAt
      });
      if (!writeSaveOutbox(queued)) {
        try {
          await writeCloudSaveDirectly(uid, slot, jsonString);
          return { localSaved, pendingCloudSaves: 0, cloudStatus: 'synced' } satisfies SaveWriteResult;
        } catch (error) {
          console.error('로컬 재시도 큐를 저장하지 못해 클라우드 직접 저장도 실패했습니다:', error);
          return { localSaved, pendingCloudSaves: 0, cloudStatus: 'local-only' } satisfies SaveWriteResult;
        }
      }
      const remaining = await flushQueuedCloudSavesForCurrentUser();
      const pendingCloudSaves = pendingCloudSaveCountForUser(uid, remaining);
      return {
        localSaved: true,
        pendingCloudSaves,
        cloudStatus: pendingCloudSaves > 0 ? 'pending' : 'synced'
      } satisfies SaveWriteResult;
    }
    // If the campaign itself could not be written locally, there is no safe
    // fallback without an account-bound cloud slot. Preserve that distinction
    // so the UI can explain the recovery action instead of claiming success.
    return { localSaved, pendingCloudSaves: 0, cloudStatus: 'local-only' } satisfies SaveWriteResult;
  },
  load: async (key: string, fallback: any) => {
    let localValue: any = null;
    try {
      const raw = localStorage.getItem(key);
      if (raw) localValue = JSON.parse(raw);
    } catch {}
    if (isFirebaseConfigured && db) {
      try {
        const currentUser = auth?.currentUser;
        if (currentUser && readCloudAccountBinding() === currentUser.uid) {
          const docRef = doc(db, 'saves', cloudSaveDocumentId(currentUser.uid));
          const snap = await withTimeout(getDoc(docRef));
          if (snap.exists()) {
            const data = snap.data() as Record<string, unknown>;
            const slots = readCloudSlotsFromDocument(data, snapshotUpdatedAt(snap));
            const activeRecord = slots.records[readActiveCloudSlot() - 1] || slots.records[0];
            const rawPayload = activeRecord
              ? await readCloudSlotPayload(activeRecord, currentUser.uid)
              : (typeof data[key] === 'string' ? data[key] : null);
            if (!rawPayload) {
              return localValue || fallback;
            }
            const cloudValue = JSON.parse(rawPayload);
            const resolved = resolveRevisionConflict(localValue, cloudValue);
            if (resolved.conflict) {
              localStorage.setItem('apawthecaria_sync_status', 'same-revision-conflict-local-kept');
              console.warn('같은 저장 버전의 내용이 달라 로컬 기록을 보존했습니다.');
            }
            return resolved.state;
          }
        }
      } catch (e) {
        console.error('Firebase 로드 에러:', e);
      }
    }
    return localValue || fallback;
  }
};

